GimCorpus.put(463,0,[[2,11,"אשה ששאלה וכו' עד נכנס תחתיה. א\"א והוא שקיבל אותה על עצמו בשאלה עכ\"ל:",1,0],[4,5,"ואם ת\"ח הוא המפקיד. א\"א ואם ת\"ח הוא הנפקד:",1,0],[5,6,"נמצא מחוייב שבועה וכו' עד וכזה הורו רבותי. א\"א ורבותי אין מורין כן לפי שאינו דומה לחמשין ידענא וחמשין לא ידענא דהתם הוה ליה למידע ואערומי הוא דמערים ותובע נמי טוען עליה ואמר מידע ידעת ודבר שבמניין קא טעין ליה ודבר שבמניין קא כפר ליה והוה ליה מחוייב שבועה שאינו יכול לישבע ומשלם אבל הני לאו הכי הוא והיינו טעמא דשק צרור דאמרינן עלה ישבע זה ויטול ולא אמרו יטול בלא שבועה עכ\"ל:",1,0],[5,7,"מעשה באחד שהפקיד שק צרור אצל חבירו וכו' עד בה' טוען ונטען יתבארו עיקרי הדברים. א\"א אין זה כלום שהרי היה שם שק ומטכסין והודה בשק וכפר במטכסין ועוד בדבריו בשק צרור למה נשבע בעל השק ונוטל לאו היינו אמרינן לגבי שוורים דקאמר ניזק ברי ומזיק שמא אכתי היינו דרבה בר נתן ותו לא מידי עכ\"ל:",1,0],[6,2,"טען השומר שתנאי וכו' עד ושהיה ביניהם תנאי. א\"א זהו תימה וכי העדים לא שמעו התנאי ואיך נאמן לומר תנאי היה בינינו וכיון שהפקיד סתם בפניהם הרי נעשה שומר גמור והוא מודה שפשע ומה לו לשקר במקום עדים לא אמרינן עכ\"ל:",1,0],[6,3,"שומר חנם שהביא ראייה וכו' ואם טען ואמר תנאי היה בינינו וכו'. א\"א תימה גדול יש בזה ואם טען ואמר לא הייתי שומר אלא הא ביתא קמך אמרתי כי יש עדים שפשע מאי הוי אלא נשבע היסת שלא היה שומר ואם בשהפקיד אצלו בעדים קאמר דאינו יכול לומר תנאי היה קשיא רישא דמה לו לשקר במקום עדים כמו שכתבתי עכ\"ל:",1,0],[6,4,"מעשה באחד שהפקיד שומשמין וכו' עד כמו שביארנו. א\"א למה בנקיטת חפץ והלא המפקיד אצל חבירו בעדים אינו צריך להחזיר לו בעדים עכ\"ל:",1,0],[7,1,"המפקיד פירות אצל חבירו וכו' עד על פירות אחרות. א\"א ועכשיו באלו המקומות שאין תורמין ומעשרין מוכרן למי שירצה עכ\"ל:",1,0],[8,3,"כל הקונה הכפל וכו' עד ואינו משלם אלא סלע. א\"א דוקא שבא השבח אחר ששלם או שאמר הריני משלם עכ\"ל:",1,0]]);
